# keys: n,y,when,where,lane,by,group,wiki,mat,crew,size,summary,steps,tricks,legacy,conn
A='Ancient & classical wonders'
E=[
dict(n="Great Pyramid of Giza",y=-2560,when="c. 2600–2560 BCE (about 20 years)",where="Giza, Egypt",lane="Africa",by="Pharaoh Khufu; overseer Hemiunu",group=A,wiki="Great_Pyramid_of_Giza",
 mat="About 2.3 million limestone blocks (avg 2.5 t), Tura white limestone casing, Aswan granite beams up to 80 t",crew="About 20,000–30,000 paid workers in rotating gangs, not slaves",size="146.6 m tall originally; base 230.3 m per side",
 summary="The largest of the Giza pyramids, built as Khufu's tomb, was the tallest human-made structure for about 3,800 years. Its base is level to within about 2 cm and aligned to true north to within a fraction of a degree.",
 steps=["Surveying: the site was levelled on bedrock, probably by cutting water channels or using plumb lines and set squares, and aligned to north using stars such as those circling the pole.","Quarrying: most blocks were cut from a quarry just south of the pyramid using copper chisels, wooden wedges and dolerite pounders; casing stone came by boat from Tura across the Nile and granite 800 km from Aswan.","Transport: blocks were dragged on wooden sledges; a tomb painting shows a worker pouring water in front of a sledge, which experiments show halves the friction on sand. A harbour and canal brought boats close to the plateau during the flood season.","Raising: ramps — straight, zigzagging up a face, or spiralling around the pyramid — carried blocks upward; levers adjusted their final position. A ramp with post holes found at the Hatnub quarry (2018) suggests sledges were hauled with rope-and-post systems.","Inner chambers: the King's Chamber was roofed with nine granite beams, and five relieving chambers above spread the enormous weight; the Grand Gallery's corbelled roof rises 8.6 m.","Casing: polished white limestone blocks were set from the top down as the ramps were removed, making the pyramid gleam; most were later taken to build Cairo."],
 tricks="The diary of an official named Merer, found at Wadi al-Jarf in 2013, records his team shipping Tura limestone to Giza — the oldest inscribed papyri ever found. Workers' villages excavated by Mark Lehner contain bakeries, breweries, cattle bones and a cemetery where workers were buried with honour, some with healed fractures showing medical care. Gang names like 'Friends of Khufu' were painted on blocks.",
 legacy="The only surviving Wonder of the Ancient World; it shows the organising power of the early Egyptian state.",conn="Ancient Egypt; Old Kingdom of Egypt; Great Pyramid built; Imhotep; Ancient aliens built the pyramids"),
dict(n="Colosseum",y=80,when="70–80 CE",where="Rome, Italy",lane="Europe",by="Emperors Vespasian and Titus (Flavian dynasty)",group=A,wiki="Colosseum",
 mat="Travertine limestone (100,000 m³), tuff, brick-faced Roman concrete, 300 t of iron clamps",crew="Thousands of workers including Jewish captives from the siege of Jerusalem",size="189 × 156 m; 48 m high; seated 50,000–80,000",
 summary="The Flavian Amphitheatre was built on the drained lake of Nero's Golden House, paid for partly with treasure looted from the Jerusalem Temple. It hosted gladiator fights, animal hunts and executions for nearly 400 years.",
 steps=["Draining Nero's lake and laying a ring-shaped concrete foundation about 12 m deep.","Building a skeleton of travertine piers, linked by arches, in 80 radial walls — so the structure could rise in several sections at once by different teams.","Vaulting: concrete barrel and groin vaults over the corridors carried the seating, using wooden centring.","Facade: three storeys of arches framed by Tuscan, Ionic and Corinthian half-columns, topped by a solid attic with sockets for the velarium masts.","Hypogeum (added under Domitian): underground tunnels, cages and about 60 lifts and trapdoors to raise animals and scenery into the arena.","Velarium: a retractable awning of canvas, worked by sailors from the Misenum fleet, shaded spectators."],
 tricks="80 numbered entrances (vomitoria) let the crowd enter and leave in minutes, and tickets (tesserae) showed seat sections — principles still used in stadiums. The arena may even have been flooded for mock sea battles in its early years. The iron clamps were later looted, leaving the pockmarks visible today.",
 legacy="The model for modern stadiums; a symbol of both Roman engineering and spectacle based on violence.",conn="Roman Empire; Julio-Claudian dynasty; Siege of Jerusalem; Roman concrete"),
dict(n="Pantheon dome",y=125,when="c. 113–125 CE",where="Rome, Italy",lane="Europe",by="Emperor Hadrian (possibly architect Apollodorus of Damascus)",group=A,wiki="Pantheon,_Rome",
 mat="Roman concrete (lime, volcanic ash pozzolana, aggregate), brick, granite columns from Egypt",crew="Unknown",size="Dome 43.3 m diameter — the interior would fit a perfect sphere",
 summary="Nearly 1,900 years later, the Pantheon still has the largest unreinforced concrete dome in the world. Its 8.2 m oculus is the only source of light.",
 steps=["Rotunda walls 6 m thick were built with hidden relieving arches and niches to channel weight.","A huge wooden centring (temporary formwork) supported the dome while concrete was laid in horizontal rings.","Lighter aggregate was used higher up: heavy basalt at the base, then tuff and finally pumice near the top.","Coffers (sunken panels) were moulded into the inner surface, reducing weight while adding beauty.","The dome thins from 6.4 m at the base to 1.2 m around the oculus, which is ringed by a compression ring of brick."],
 tricks="Roman concrete with volcanic ash forms crystals that make it stronger over time; MIT research in 2023 found 'lime clasts' that let cracks heal themselves when water seeps in.",
 legacy="It inspired Brunelleschi's Florence dome, St Peter's, and the US Capitol.",conn="Roman Empire; Hagia Sophia"),
dict(n="Roman aqueducts",y=-312,when="312 BCE – 3rd century CE",where="Rome and across the empire",lane="Europe",by="Roman engineers; Appius Claudius (first aqueduct)",group=A,wiki="Roman_aqueduct",
 mat="Stone, brick, concrete, waterproof lime mortar (opus signinum), lead pipes",crew="Soldiers, slaves, contracted workers",size="Rome's 11 aqueducts were about 800 km long and delivered perhaps 1 million m³ a day",
 summary="Aqueducts carried water by gravity alone from springs in the hills to cities, feeding fountains, baths and toilets. Most of their length ran underground; the famous arches were only needed to cross valleys.",
 steps=["Surveyors used a chorobates (a 6 m levelling table with a water channel) and groma to plan a route with a gentle, constant slope — the Pont du Gard's aqueduct drops just 12.6 m over 50 km.","Tunnels were dug through hills from shafts at intervals, teams meeting in the middle.","Valleys were crossed with arcades of stacked arches, or with inverted siphons — lead or stone pipes going down and up under pressure.","The channel (specus) was lined with waterproof mortar and covered against dirt and sunlight.","Settling tanks removed sediment; at the city, a distribution castle (castellum) split water to public fountains first, then baths, then private houses."],
 tricks="Frontinus, water commissioner in 97 CE, wrote a manual exposing illegal taps by citizens. Some aqueducts, like Segovia's, worked until the 20th century.",
 legacy="Modern water supply systems follow the same principles; the Aqua Virgo still feeds the Trevi Fountain.",conn="Roman Republic; Roman Empire; Pont du Gard"),
dict(n="Roman roads",y=-312,when="From 312 BCE",where="Across the Roman Empire",lane="Europe",by="Roman army engineers",group=A,wiki="Roman_roads",
 mat="Layers of rubble, gravel, sand, lime concrete and fitted paving stones",crew="Legionaries and slaves",size="About 80,000 km of paved roads",
 summary="Roman roads let legions march 30 km a day and carried trade and messages across the empire; 'all roads lead to Rome'.",
 steps=["Surveying a straight route with a groma.","Digging a trench about 1 m deep.","Laying a foundation of large stones (statumen), then rubble in lime (rudus), then fine gravel concrete (nucleus).","Setting fitted paving stones (summa crusta) with a camber so rain drained into side ditches.","Adding milestones every Roman mile and way-stations (mansiones) for changing horses."],
 tricks="The Via Appia (312 BCE) is still walkable today. The cursus publicus courier system could carry messages 80 km a day.",
 legacy="Many modern European highways follow Roman routes.",conn="Roman Republic; Roman Empire"),
dict(n="Great Wall of China",y=-221,when="7th century BCE – 1644 CE (mostly Ming)",where="Northern China",lane="East Asia",by="Warring States, Qin Shi Huang, Han, and especially the Ming dynasty",group=A,wiki="Great_Wall_of_China",
 mat="Rammed earth, wood, stone; Ming brick laid with lime mortar mixed with sticky rice",crew="Soldiers, peasants and convicts; hundreds of thousands died",size="All walls total about 21,196 km",
 summary="Not one wall but many, built over 2,000 years to defend against northern nomads. The brick sections tourists see near Beijing are Ming, mostly 16th century.",
 steps=["Early walls were rammed earth: soil packed in layers between wooden frames.","Qin Shi Huang's general Meng Tian linked older walls after 221 BCE with 300,000 men.","The Han extended walls into the Gansu desert using layers of reeds, gravel and sand.","The Ming rebuilt sections in brick and stone, with watchtowers on ridges.","Beacon towers used smoke by day and fire by night to send warnings hundreds of kilometres in hours."],
 tricks="Chemists confirmed (2010) that Ming builders mixed sticky rice soup with lime, creating mortar stronger and more water-resistant than lime alone. It is not visible from the Moon with the naked eye — a famous myth.",
 legacy="A symbol of China, and a UNESCO site.",conn="Qin dynasty; Qin Shi Huang; Han dynasty; Ming dynasty; Great Wall unified by Qin"),
dict(n="Stonehenge",y=-2500,when="c. 3000–1500 BCE",where="Wiltshire, England",lane="Europe",by="Neolithic and Bronze Age Britons",group=A,wiki="Stonehenge",
 mat="Sarsen stones up to 25 t; bluestones of 2–5 t from Wales",crew="Hundreds of people over generations",size="Outer circle 33 m across",
 summary="Stonehenge's giant stones align with the midsummer sunrise and midwinter sunset. Bluestones were dragged about 225 km from the Preseli Hills in Wales.",
 steps=["A circular ditch and bank were dug with antler picks around 3000 BCE.","Bluestones were brought from Wales, probably on sledges and rollers.","Sarsens were shaped by pounding with stone hammers.","Stones were tipped into pits and hauled upright with ropes and A-frames.","Lintels were lifted on timber platforms and fixed with woodworking joints — mortise-and-tenon and tongue-and-groove."],
 tricks="Analysis in 2024 traced the Altar Stone to northern Scotland, over 700 km away.",legacy="A UNESCO site and icon of prehistory.",conn="Neolithic Revolution; Bronze Age"),
dict(n="Göbekli Tepe",y=-9600,when="c. 9600–8200 BCE",where="Şanlıurfa, Turkey",lane="Middle East",by="Hunter-gatherers",group=A,wiki="G%C3%B6bekli_Tepe",
 mat="Limestone pillars up to 5.5 m and 10 t",crew="Probably hundreds of foragers gathering for feasts",size="Several circular enclosures up to 30 m across",
 summary="Built 6,000 years before Stonehenge by people who did not farm, it overturned the idea that monuments only came after agriculture.",
 steps=["Pillars were cut from the limestone plateau with flint tools.","T-shaped pillars were carved with foxes, boars, snakes, vultures and human arms and belts.","Pillars were set in stone walls in circles, with two central pillars.","Large feasts with wild game and possibly beer brought people together to build.","Enclosures were later deliberately backfilled."],
 tricks="Its builders were hunter-gatherers; nearby, some of the earliest domesticated wheat appeared, suggesting monument building may have encouraged farming.",legacy="Called the world's first temple.",conn="Göbekli Tepe built; Neolithic Revolution"),
dict(n="Hagia Sophia",y=537,when="532–537 CE",where="Constantinople (Istanbul)",lane="Europe",by="Justinian I; architects Anthemius of Tralles and Isidore of Miletus",group=A,wiki="Hagia_Sophia",
 mat="Brick, lime mortar, marble from across the empire",crew="About 10,000 workers",size="Dome 31 m across, 55 m high",
 summary="Built in under six years after the Nika riots, it was the world's largest cathedral for nearly a thousand years.",
 steps=["Four great piers and arches formed a square base.","Pendentives — curved triangles — made the transition from square to circular dome base.","The shallow dome of light bricks rose on 40 ribs with windows at its base, making it seem to float on light.","Semi-domes on two sides extended the space.","Gold mosaics covered the interior."],
 tricks="The original dome collapsed after an earthquake in 558 and was rebuilt higher; Ottoman architect Sinan later added buttresses.",legacy="Church, mosque (1453), museum (1934), mosque again (2020).",conn="Byzantine Empire; Justinian I; Fall of Constantinople; Ottoman Empire"),
dict(n="Petra",y=-100,when="c. 4th century BCE – 1st century CE",where="Jordan",lane="Middle East",by="Nabataeans",group=A,wiki="Petra",
 mat="Rose-red sandstone carved in place",crew="Nabataean stonemasons",size="Al-Khazneh facade about 40 m high",
 summary="The Nabataean capital, a trading hub on incense routes, is famous for tombs carved into cliffs.",
 steps=["Masons cut steps into the cliff to reach the top.","They carved downward from the top, so no scaffolding was needed.","Chambers were hollowed out behind facades.","Dams, cisterns and channels captured flash floods to supply water."],
 tricks="Nabataean water engineering supplied up to 30,000 people in a desert.",legacy="A UNESCO World Heritage Site.",conn="Roman Empire"),
dict(n="Machu Picchu",y=1450,when="c. 1450",where="Peru",lane="Americas",by="Inca emperor Pachacuti",group=A,wiki="Machu_Picchu",
 mat="Granite cut on site",crew="Mit'a labourers",size="About 200 structures on a mountain ridge at 2,430 m",
 summary="A royal estate perched on a ridge, built without mortar, wheels or iron tools.",
 steps=["Engineers built foundations — perhaps 60% of the work is underground.","Terraces with layered drainage stopped landslides.","Granite was split along natural cracks and shaped with harder stones.","Ashlar blocks were fitted so precisely no blade fits between them."],
 tricks="Its drainage and mortarless walls flex during earthquakes; blocks 'dance' and settle back.",legacy="A UNESCO site rediscovered by the outside world in 1911.",conn="Inca Empire; Pachacuti"),
dict(n="Angkor water system",y=1150,when="9th–13th centuries",where="Cambodia",lane="Southeast Asia",by="Khmer kings",group=A,wiki="Angkor",
 mat="Earth embankments, laterite, sandstone",crew="Hundreds of thousands",size="West Baray reservoir 8 × 2.1 km",
 summary="Angkor was a 'hydraulic city' whose reservoirs and canals managed monsoon water.",
 steps=["Engineers built huge barays (reservoirs) with earthen dykes.","Canals moved water and stone.","Moats around temples stabilised the sandy soil under the foundations.","Lidar shows a city covering 1,000 km²."],
 tricks="Angkor Wat's sandstone was floated on canals from Kulen hills 40 km away.",legacy="Its decline may have been caused by droughts and floods overwhelming the system.",conn="Khmer Empire; Angkor Wat built"),
]
